///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.ThisTabBind
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.ThisTabBind = function () {
    /* sdd-asis-lifecycle:begin ThisTabBind — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const btns = $('section.contents nav.tabgroup li');
    btns.each(function(i) {
            $(this).data("idx", i);
    });
    btns.each(function(i) {
            const a = $(this).children("a");
            a.bind("click focus", function() {
                    $(this).parent().parent().children("li").removeClass("active");
                    $(this).parent().addClass("active");
                    const idx = $(this).parent().data("idx");
                    $('article.pcontents div.tabBlock div.block-ctt').addClass("hide");
                    $('article.pcontents div.tabBlock div.block-ctt').eq(idx).removeClass("hide");
            });
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.lawItemView
 * @author Inswave
 * @date 2026. 09. 29
 * @param ldMktTp ipt_lawItmSeq
 * @returns
 * @hidden N
*/
scwin.lawItemView = function (ldMktTp, ipt_lawItmSeq) {
    /* sdd-asis-lifecycle:begin fn_LawItemView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ldMktTp === '1') {
        $c.util.getComponent('ipt_lawNo').setValue("LAW0000003");
    } else {
        if (ldMktTp === '2') {
            $c.util.getComponent('ipt_lawNo').setValue("LAW0000001");
        }
    }
    $c.util.getComponent('ipt_lawItmSeq').setValue(ipt_lawItmSeq);
    $c.util.getComponent('ipt_method').setValue("searchRegulationSystemPop");
    $c.util.getComponent('ipt_forward').setValue("regulationsystem_popup1");
    $("#lawItemForm").one("submit", function() {
            $c.win.openPopup('', { id: "pop_target", scrollbars: true, resizable: false, width: "440", height: "500", type: "pageFramePopup" }, {});
            this.action = "/disclosureinfo/regulationsystem.do";
            this.target = "pop_target";
    }).trigger("submit");
    /* sdd-asis-lifecycle:end */
};
